def corpus():
    return _corpus(SCRIPTS, "calibration", "docmee-conversations-v1")


def heldout_corpus():
    return _corpus(HELDOUT_SCRIPTS, "heldout", "docmee-conversations-heldout-v1")


def _corpus(scripts, split, version, options=OPTIONS):
    cases = []
    for conversation_id, language, turns in scripts:
        history = []
        for index, (customer, expected, assistant) in enumerate(turns, 1):
            history.append("Customer: " + customer)
            cases.append({"id": f"{conversation_id}.turn-{index}", "split": split,
                          "task": "workflow_branch", "language": language, "category": conversation_id,
                          "text": "Scripted transcript. Route the current customer turn (last Customer line), "
                                  "not an earlier request.\n" + "\n".join(history),
                          "candidates": [{"id": key, "label": label} for key, label in options],
                          "expected": expected})
            if assistant:
                history.append("Assistant (scripted context): " + assistant)
    return evaluation.validate_corpus({"schemaVersion": 1, "version": version,
                                       "synthetic": True, "cases": cases})


def description_corpus(split, variant):
    if split not in ("calibration", "heldout") or variant not in ("baseline", "distinct"):
        raise ValueError("invalid description experiment")
    scripts = SCRIPTS + HELDOUT_SCRIPTS if split == "calibration" else DESCRIPTION_HELDOUT_SCRIPTS
    options = OPTIONS if variant == "baseline" else DISTINCT_OPTIONS
    return _corpus(scripts, split, "docmee-descriptions-v1-" + variant, options)


def framing_corpus(split, variant):
    if split not in ('calibration', 'heldout') or variant not in ('json', 'text'):
        raise ValueError('invalid framing experiment')
    scripts = (SCRIPTS + HELDOUT_SCRIPTS + DESCRIPTION_HELDOUT_SCRIPTS
               if split == 'calibration' else FRAMING_HELDOUT_SCRIPTS)
    # Deliberately identical corpus/hash: only the native serialization differs.
    return _corpus(scripts, split, 'docmee-framing-v1', OPTIONS)


def run_framing(*, pins, variant, timeout=5, split='calibration'):
    data = framing_corpus(split, variant)
    report = evaluation.evaluate(data, split=split, pins=pins, timeout=timeout)
    report.update(simulationMode='scripted_transcript_route_replay', executesDocmeeWorkflow=False,
                  sendsExternalMessages=False, usesPatientData=False, assistantContext='fixed_script',
                  framingVariant=variant,
                  evaluationPurpose='observed_regression' if split == 'calibration' else 'fresh_heldout')
    report['byConversation'] = {
        key: evaluation._metrics([case for case in report['cases'] if case['category'] == key])
        for key in sorted({case['category'] for case in data['cases']})}
    return report


def run_descriptions(*, pins, variant, timeout=5, split="calibration"):
    data = description_corpus(split, variant)
    report = evaluation.evaluate(data, split=split, pins=pins, timeout=timeout)
    report.update(simulationMode="scripted_transcript_route_replay", executesDocmeeWorkflow=False,
                  sendsExternalMessages=False, usesPatientData=False, assistantContext="fixed_script",
                  descriptionVariant=variant,
                  evaluationPurpose="observed_regression" if split == "calibration" else "fresh_heldout")
    report["byConversation"] = {
        key: evaluation._metrics([case for case in report["cases"] if case["category"] == key])
        for key in sorted({case["category"] for case in data["cases"]})}
    return report


def run(*, pins, timeout=5, split="calibration"):
    if split not in ("calibration", "heldout"):
        raise ValueError("invalid conversation split")
    scripts = SCRIPTS if split == "calibration" else HELDOUT_SCRIPTS
    data = corpus() if split == "calibration" else heldout_corpus()
    report = evaluation.evaluate(data, split=split, pins=pins, timeout=timeout)
    report.update(simulationMode="scripted_transcript_route_replay", executesDocmeeWorkflow=False,
                  sendsExternalMessages=False, usesPatientData=False, assistantContext="fixed_script")
    report["byConversation"] = {
        key: evaluation._metrics([case for case in report["cases"] if case["category"] == key])
        for key, _, _ in scripts}
    return report


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--model-version", required=True)
    parser.add_argument("--calibration-version", required=True)
    args = parser.parse_args()
    report = run(pins=(args.model_version, args.calibration_version))
    print(json.dumps(report, ensure_ascii=True, allow_nan=False, indent=2))
    return 0 if report["complete"] and report["summary"]["accuracy"] == 1 else 1


if __name__ == "__main__":
    raise SystemExit(main())
